#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Threading.Tasks;
namespace FileCompass {
 internal static class ToolDialogsPolishTests {
  static void Pump(){NavigationTests.Wait(Task.Delay(100));}
  static void Open(Window w){w.Left=-18000;w.Top=-18000;w.ShowActivated=false;w.Show();Pump();w.UpdateLayout();}
  internal static int Run(string root){Directory.CreateDirectory(root);var log=new List<string>();var windows=new List<Window>();try{Action<bool,string> check=delegate(bool yes,string label){if(!yes)throw new Exception(label);log.Add(label);};L.ChangeLanguage("cs");
   var main=new MainWindow(root,new ProgramSettings{AutoRefresh=false}){Width=1740,Height=900};windows.Add(main);Open(main);NavigationTests.WaitPanels(main);var toolbar=FluentUiTests.Children<Border>(main).Single(x=>Convert.ToString(x.Tag)=="main-toolbar-frame");Func<string,Button> action=key=>AdvancedToolsTests.Visual<Button>(toolbar).Single(x=>FluentUiTests.Children<Image>(x).Any(i=>Convert.ToString(i.Tag)==key));check(action("view").TranslatePoint(new Point(),toolbar).X<action("edit").TranslatePoint(new Point(),toolbar).X&&action("edit").TranslatePoint(new Point(),toolbar).X<action("picture").TranslatePoint(new Point(),toolbar).X,"toolbar order is Preview, Editor, Thumbnails");
   var converter=new MediaConverterWindow(main,new string[0],root,true,delegate{},delegate{});windows.Add(converter);Open(converter);if(converter.AnalysisTask!=null)NavigationTests.Wait(converter.AnalysisTask);
   foreach(bool audio in new[]{false,true}){converter.Mode.SelectedIndex=audio?1:0;Pump();foreach(var size in new[]{new Size(1180,820),new Size(800,620)}){converter.Width=size.Width;converter.Height=size.Height;Pump();converter.UpdateLayout();var files=AdvancedToolsTests.Visual<DataGrid>(converter).Single();var folder=converter.Folder;double gap=files.TranslatePoint(new Point(),converter).Y-folder.TranslatePoint(new Point(0,folder.ActualHeight),converter).Y;check(gap>=14,"destination is separated from queue: "+audio+" / "+size);check(files.ActualHeight>=64,"converter retains readable queue height: "+audio+" / "+size);NextStageTests.Draw(converter,Path.Combine(root,"converter-"+(audio?"audio":"images")+"-"+size.Width+".png"));}}converter.Close();windows.Remove(converter);
   var smart=new DiskSmartWindow(main,false);windows.Add(smart);Open(smart);var disks=Enumerable.Range(0,8).Select(i=>SmartDisk.Parse("/dev/sd"+(char)('a'+i),"ata","{\"model_name\":\"Ukázkový disk "+(i+1)+"\",\"smart_status\":{\"passed\":true},\"temperature\":{\"current\":38},\"user_capacity\":{\"bytes\":500000000000}} ")).ToList();smart.SetResults(disks);Pump();check(smart.Disks.IsVisible&&smart.Disks.ActualHeight>=80,"SMART disk tiles are visible below the common title");var next=FluentUiTests.Children<Button>(smart).Single(x=>Convert.ToString(x.ToolTip)=="Další disk");next.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(smart.Disks.SelectedIndex==1&&smart.Snapshot.Model==disks[1].Model,"next arrow switches selected disk and its details");smart.Disks.SelectedIndex=7;Pump();check(!next.IsEnabled,"next arrow is disabled at the final disk");var previous=FluentUiTests.Children<Button>(smart).Single(x=>Convert.ToString(x.ToolTip)=="Předchozí disk");previous.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(smart.Disks.SelectedIndex==6,"previous arrow works after scrolling to a later disk");NextStageTests.Draw(smart,Path.Combine(root,"smart.png"));smart.Close();windows.Remove(smart);
   foreach(var protocol in new[]{NetworkProtocol.FTP,NetworkProtocol.SFTP,NetworkProtocol.SMB}){var profile=new NetworkProfile{Protocol=protocol,Name="Ukázkové připojení",Host="example.invalid",UserName="tester",Port=protocol==NetworkProtocol.FTP?21:22};var dialog=new NetworkProfileDialog(main,profile);windows.Add(dialog);Open(dialog);var passwords=FluentUiTests.Children<PasswordBox>(dialog).Where(x=>x.IsVisible).ToArray();check(passwords.Length>0,"visible password field exists for "+protocol);foreach(var password in passwords){password.Password="synthetic-fixture";password.Focus();Pump();check(password.ActualHeight>=30&&password.ActualHeight<=34&&password.FocusVisualStyle==null,"password uses standard field height and no duplicate focus frame: "+protocol);var host=password.Template.FindName("PART_ContentHost",password) as ScrollViewer;check(host!=null&&host.ActualHeight>=password.FontSize,"password glyphs have sufficient content height: "+protocol);}NextStageTests.Draw(dialog,Path.Combine(root,"profile-"+protocol+".png"));dialog.Close();windows.Remove(dialog);}
   var target=new NetworkProfile{Protocol=NetworkProtocol.FTP,Name="Ukázkový FTP",Host="example.invalid",UserName="tester",Port=21};foreach(var rule in new[]{NetworkCopyRule.Resume,NetworkCopyRule.Skip,NetworkCopyRule.Overwrite}){var transfer=new NetworkCopyDialog(main,2,root,"/backup",null,target);transfer.Left=-18000;transfer.Top=-18000;bool? answer=null;transfer.Loaded+=delegate{transfer.Dispatcher.BeginInvoke(new Action(delegate{Pump();transfer.SelectRule(rule);Pump();var footer=FluentUiTests.Children<Border>(transfer).Single(x=>Convert.ToString(x.Tag)=="dialog-footer");check(transfer.RulePicker.IsVisible&&transfer.RulePicker.Items.Count==3&&transfer.RulePicker.TranslatePoint(new Point(0,transfer.RulePicker.ActualHeight),transfer).Y<=footer.TranslatePoint(new Point(),transfer).Y,"compact collision dropdown is fully visible: "+rule);check(transfer.IsVisible,"selecting collision rule does not start a transfer: "+rule);if(rule==NetworkCopyRule.Resume)NextStageTests.Draw(transfer,Path.Combine(root,"network-copy.png"));transfer.Start.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}));};answer=transfer.ShowDialog();check(answer==true&&transfer.Rule==rule,"single start action returns selected rule: "+rule);}
   var activity=main.AddDockTransferForTests("Přenos souborů",delegate{});activity.TransferRoute="FTP · Ukázkový soubor.mp4 · 51 % · 107 MiB/s · 00:01:55";activity.Update("Přenos",.51,.56);main.RefreshTaskDock();Pump();main.UpdateLayout();var tile=FluentUiTests.Children<ActivityTile>(main).Single();var texts=FluentUiTests.Children<TextBlock>(tile).Where(x=>!String.IsNullOrEmpty(x.Text)).ToArray();check(texts.All(x=>x.FontSize>=13),"background activity text is at least 13 DIP in the real main window");check(tile.ActualHeight>=80,"larger activity text has a taller card");NextStageTests.Draw(main,Path.Combine(root,"background.png"));activity.Finish("Hotovo",true);
   main.Close();windows.Remove(main);File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"FAIL: "+ex}));return 1;}finally{foreach(var w in windows.ToArray().Reverse())w.Close();}}
 }
}
#endif
